# Copies the Portal 2 files the test map's models use into a few parts under 30 MB,
# on your Desktop in "p2bundle2". It only reads your Portal 2 files.
# If Steam isn't in the default place, change the first line to your "Portal 2\portal2" folder.
$p2 = "C:\Program Files (x86)\Steam\steamapps\common\Portal 2\portal2"
$out = "$env:USERPROFILE\Desktop\p2bundle2"
New-Item -ItemType Directory -Force $out | Out-Null
$list = "8,36429400,175008,1;0,115940968,1255,1;0,188576176,87576,1;0,188532320,43856,1;0,115341234,349784,1;0,115691018,175008,1;5,201230042,87568,1;5,201208010,22032,1;5,192110213,87640,1;5,192088109,22104,1;5,180602789,175008,1;0,193758440,175008,1;5,155590739,175008,1;5,155415731,175008,1;5,146414894,43936,1;5,146403726,11168,1;5,146381622,22104,1;1,54004551,43912,1;1,54048463,43912,1;1,54092375,43912,1;1,54136287,43936,1;1,54180223,43936,1;0,208436820,699264,1;0,209136084,349720,1;0,131916713,1398360,1;5,94777716,349784,1;5,94427932,349784,1;0,147984961,1398360,1;0,149383321,1398368,1;0,133323454,22032,1;0,198950252,11168,1;5,71450260,87640,1;5,71362620,87640,1;5,68171748,349784,1;0,195676989,2796448,1;5,4370471,699296,1;5,3146656,1048807,1;0,102076726,5592664,1;0,107669390,349784,1;4,206453304,5592664,1;4,184534888,175008,1;4,184185104,349784,1;4,183835320,349784,1;0,192710622,699296,1;4,158051704,87640,1;4,157352136,349784,1;4,157002352,349784,1;4,150751336,699296,1;4,150729232,22104,1;4,134994896,175008,1;4,130623104,43936,1;4,130404160,175008,1;4,129704864,699296,2;4,129005568,699296,2;4,128306272,699296,2;4,127606976,699296,2;4,125509304,1398368,2;4,124110936,1398368,2;4,122712576,1398360,2;4,119915848,1398368,2;4,118517488,1398360,2;4,117119120,1398368,2;4,115796024,11168,2;4,115446008,175008,2;4,115434840,11168,2;4,114734616,175008,2;4,114035320,699296,2;4,110189056,349784,2;4,109095840,43936,2;4,109008200,87640,2;4,108658480,349720,2;4,108133688,349784,2;4,108132760,928,2;4,107607968,349784,2;4,105246656,87640,2;4,105071648,175008,2;4,104372352,699296,2;4,94582920,2796456,2;4,84794328,699296,2;4,84095032,699296,2;4,83395736,699296,2;4,82696440,699296,2;4,81647352,699304,2;4,81297632,349720,2;4,80598368,699264,2;4,79700840,175008,2;4,71528528,1398360,2;4,67747704,699264,2;4,67048440,699264,2;4,53414040,175008,2;4,50617592,2796448,2;4,42040568,175008,2;4,40116680,699296,3;4,38718320,1398360,3;0,133508329,1398360,3;4,29015624,349784,3;4,24994616,699264,3;3,194527303,699296,3;3,185742183,1398360,3;3,184343823,1398360,3;3,181371903,1398360,3;43,35228784,699288,3;43,22247176,43928,3;43,22072176,175000,3;114,12992718,2796440,3;43,175000,699288,3;43,0,175000,3"
$streams = @{}
foreach ($e in $list.Split(";")) {
  $a = $e.Split(","); $arch = [int]$a[0]; $off = [long]$a[1]; $len = [int]$a[2]; $part = [int]$a[3]
  if (-not $streams.ContainsKey($part)) { $streams[$part] = [IO.File]::Create("$out\part$part.bin") }
  $src = [IO.File]::OpenRead(("{0}\pak01_{1:D3}.vpk" -f $p2, $arch))
  [void]$src.Seek($off, [IO.SeekOrigin]::Begin)
  $buf = New-Object byte[] $len; $n = 0
  while ($n -lt $len) { $n += $src.Read($buf, $n, $len - $n) }
  $streams[$part].Write($buf, 0, $len); $src.Close()
}
foreach ($s in $streams.Values) { $s.Close() }
Write-Host "Done. Upload the part*.bin files from $out"
